#!/usr/bin/env python3
"""Emits H800's Manual Movement and Machine Parameter pages from its label list."""
import sys, os, re
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from legacy_labels import *

NS = "Kaban.Machines.H800.Screens"
OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "Kaban.Machines.H800", "Screens")

HDR = '''\ufeff// <auto-generated>
//   Generated by tools/build_h800_pages.py from Kaban.Machines.H800/PlcLabels.csv
//
//   Addresses and names are the ENGINEER'S OWN, straight from the label list, so
//   every binding here is real. Captions are translated from the Turkish device
//   names; divisors and units are starting values chosen per data type, to be
//   corrected on the machine.
// </auto-generated>

namespace {ns}
{{
    partial class {cls}
    {{
        private System.ComponentModel.IContainer components = null;
        protected override void Dispose(bool disposing)
        {{
            if (disposing && (components != null)) components.Dispose();
            base.Dispose(disposing);
        }}

        #region Component Designer generated code
        private void InitializeComponent()
        {{
'''

FTR = '''            this.AutoScroll = true;
            this.BackColor = System.Drawing.Color.White;
            this.Name = "{cls}";
            this.Size = new System.Drawing.Size(1060, 700);
            this.ResumeLayout(false);
        }}
        #endregion
'''

CB = '''\ufeff// <auto-generated>  see the .Designer.cs  </auto-generated>
using System.Windows.Forms;

namespace {ns}
{{
    public partial class {cls} : UserControl
    {{
        public {cls}() {{ InitializeComponent(); }}
    }}
}}
'''

def emit(cls, fields, plc=1):
    decl, body, used = [], [], set()
    x, y = 16, 16
    COLW, MAXY = 512, 660

    def place(h):
        nonlocal x, y
        if y + h > MAXY: y = 16; x += COLW
        pos = (x, y); y += h + 6
        return pos

    for f in fields:
        base = ident(f["caption"])[:40] or "Field"
        nm = base; i = 2
        while nm in used: nm = base + str(i); i += 1
        used.add(nm)
        cap = f["caption"].replace('"', "'")[:48]
        k = f["kind"]

        if k == "unit":
            px, py = place(66)
            decl.append("            this.u{0} = new Kaban.UI.Controls.CylinderUnitHMI();".format(nm))
            b = ['            this.u{0}.Name = "u{0}";'.format(nm),
                 '            this.u{0}.PlcNumber = {1};'.format(nm, plc),
                 '            this.u{0}.TitleTextKey = "{1}";'.format(nm, cap),
                 '            this.u{0}.BackColor = System.Drawing.Color.White;'.format(nm),
                 '            this.u{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                 '            this.u{0}.Size = new System.Drawing.Size(480, 62);'.format(nm),
                 '            this.u{0}.LogAction = true;'.format(nm),
                 '            this.u{0}.CommandAAddress = "{1}";'.format(nm, f["b"]["addr"]),
                 '            this.u{0}.CommandAAction = Kaban.Core.Enums.BitActionType.Momentary;'.format(nm),
                 '            this.u{0}.CommandBAddress = "{1}";'.format(nm, f["a"]["addr"]),
                 '            this.u{0}.CommandBAction = Kaban.Core.Enums.BitActionType.Momentary;'.format(nm)]
            if f.get("lamp"):
                b.append('            this.u{0}.Lamp1AAddress = "{1}";'.format(nm, f["lamp"]["addr"]))
            if f.get("pos"):
                ut, sfx, dec = unit_for(f["caption"])
                b += ['            this.u{0}.PositionAddress = "{1}";'.format(nm, f["pos"]["addr"]),
                      '            this.u{0}.PositionDataType = Kaban.Core.Enums.DataTypeEnum.{1};'.format(
                          nm, "Bin_32" if is_32(f["pos"]["dtype"]) else "Bin_16"),
                      '            this.u{0}.PositionDivisor = {1}D;'.format(nm, divisor_for(f["pos"]["dtype"], ut)),
                      '            this.u{0}.PositionDecimalPlaces = {1};'.format(nm, dec),
                      '            this.u{0}.PositionDigits = 6;'.format(nm),
                      '            this.u{0}.PositionSuffix = "{1}";'.format(nm, sfx),
                      '            this.u{0}.PositionUnitType = Kaban.Core.Enums.UnitType.{1};'.format(nm, ut)]
            b.append('            this.u{0}.RequiredSecurity = Kaban.Core.Enums.SecurityLevel.Operator;'.format(nm))
            b.append('            this.Controls.Add(this.u{0});'.format(nm))
            body.append("            // \n            // u{0}\n            // \n".format(nm) + "\n".join(b) + "\n")

        elif k == "button":
            px, py = place(40)
            decl.append("            this.b{0} = new Kaban.UI.Controls.ButtonHMI();".format(nm))
            body.append("            // \n            // b{0}\n            // \n".format(nm) + "\n".join([
                '            this.b{0}.Name = "b{0}";'.format(nm),
                '            this.b{0}.PlcNumber = {1};'.format(nm, plc),
                '            this.b{0}.FallbackText = "{1}";'.format(nm, cap),
                # ButtonHMI carries a LIST of bit actions, not a single address -
                # one button can drive several relays. Momentary is right for a
                # manual command: the bit falls when the finger lifts.
                '            this.b{0}.BitActions.Add(new Kaban.Core.Models.BitAction {{ Address = "{1}", Action = Kaban.Core.Enums.BitActionType.Momentary }});'.format(nm, f["a"]["addr"]),
                '            this.b{0}.Lamp1Address = "{1}";'.format(nm, f["a"]["addr"]),
                '            this.b{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                '            this.b{0}.Size = new System.Drawing.Size(300, 36);'.format(nm),
                '            this.b{0}.LogAction = true;'.format(nm),
                '            this.b{0}.RequiredSecurity = Kaban.Core.Enums.SecurityLevel.Operator;'.format(nm),
                '            this.Controls.Add(this.b{0});'.format(nm)]) + "\n")

        elif k == "lamp":
            px, py = place(30)
            decl.append("            this.l{0} = new Kaban.UI.Controls.LampHMI();".format(nm))
            body.append("            // \n            // l{0}\n            // \n".format(nm) + "\n".join([
                '            this.l{0}.Name = "l{0}";'.format(nm),
                '            this.l{0}.PlcNumber = {1};'.format(nm, plc),
                '            this.l{0}.Address = "{1}";'.format(nm, f["a"]["addr"]),
                '            this.l{0}.DescriptionText = "{1}";'.format(nm, cap),
                '            this.l{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                '            this.l{0}.Size = new System.Drawing.Size(300, 26);'.format(nm),
                '            this.Controls.Add(this.l{0});'.format(nm)]) + "\n")

        elif k == "check":
            px, py = place(32)
            decl.append("            this.c{0} = new Kaban.UI.Controls.CheckBoxHMI();".format(nm))
            body.append("            // \n            // c{0}\n            // \n".format(nm) + "\n".join([
                '            this.c{0}.Name = "c{0}";'.format(nm),
                '            this.c{0}.PlcNumber = {1};'.format(nm, plc),
                '            this.c{0}.Address = "{1}";'.format(nm, f["a"]["addr"]),
                '            this.c{0}.DescriptionText = "{1}";'.format(nm, cap),
                '            this.c{0}.Location = new System.Drawing.Point({1}, {2});'.format(nm, px, py),
                '            this.c{0}.Size = new System.Drawing.Size(420, 28);'.format(nm),
                '            this.c{0}.LogAction = true;'.format(nm),
                '            this.c{0}.RequiredSecurity = Kaban.Core.Enums.SecurityLevel.Maintenance;'.format(nm),
                '            this.Controls.Add(this.c{0});'.format(nm)]) + "\n")

        else:   # num / display
            px, py = place(36)
            kind = "NumericInputHMI" if k == "num" else "NumericDisplayHMI"
            pfx = "n" if k == "num" else "d"
            ut, sfx, dec = unit_for(f["caption"])
            decl.append("            this.{0}{1} = new Kaban.UI.Controls.{2}();".format(pfx, nm, kind))
            body.append("            // \n            // {0}{1}\n            // \n".format(pfx, nm) + "\n".join([
                '            this.{0}{1}.Name = "{0}{1}";'.format(pfx, nm),
                '            this.{0}{1}.PlcNumber = {2};'.format(pfx, nm, plc),
                '            this.{0}{1}.Address = "{2}";'.format(pfx, nm, f["a"]["addr"]),
                '            this.{0}{1}.DataType = Kaban.Core.Enums.DataTypeEnum.{2};'.format(
                    pfx, nm, "Bin_32" if is_32(f["a"]["dtype"]) else "Bin_16"),
                '            this.{0}{1}.Divisor = {2}D;'.format(pfx, nm, divisor_for(f["a"]["dtype"], ut)),
                '            this.{0}{1}.DecimalPlaces = {2};'.format(pfx, nm, dec),
                '            this.{0}{1}.Digits = 7;'.format(pfx, nm),
                '            this.{0}{1}.Suffix = "{2}";'.format(pfx, nm, sfx),
                '            this.{0}{1}.UnitType = Kaban.Core.Enums.UnitType.{2};'.format(pfx, nm, ut),
                '            this.{0}{1}.DescriptionText = "{2}";'.format(pfx, nm, cap),
                '            this.{0}{1}.Location = new System.Drawing.Point({2}, {3});'.format(pfx, nm, px, py),
                '            this.{0}{1}.Size = new System.Drawing.Size(420, 32);'.format(pfx, nm),
                '            this.Controls.Add(this.{0}{1});'.format(pfx, nm)]) + "\n")

    fields_decl = "\n".join("        private Kaban.UI.Controls.{0} {1};".format(
        re.search(r"new Kaban\.UI\.Controls\.(\w+)\(\)", d).group(1),
        re.search(r"this\.(\w+) =", d).group(1)) for d in decl)

    text = (HDR.format(ns=NS, cls=cls) + "\n".join(decl) +
            "\n            this.SuspendLayout();\n" + "".join(body) +
            FTR.format(cls=cls) + "\n" + fields_decl + "\n    }\n}\n")

    os.makedirs(OUT, exist_ok=True)
    open(os.path.join(OUT, cls + ".Designer.cs"), "w", encoding="utf-8", newline="\r\n").write(text)
    open(os.path.join(OUT, cls + ".cs"), "w", encoding="utf-8", newline="\r\n").write(
        CB.format(ns=NS, cls=cls))
    return len(decl)

if __name__ == "__main__":
    src = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..",
                       "Kaban.Machines.H800", "PlcLabels.csv")
    rows = load_labels(src)
    mv = build_movement_fields(rows)
    pr = build_parameter_fields(rows)
    st = build_status_fields(rows)

    n1 = emit("ManualMovement", [f for f in mv if f["kind"] in ("unit", "button")])
    n2 = emit("MachineStatus",  [f for f in mv if f["kind"] == "lamp"] + st)
    n3 = emit("MachineParameters", [f for f in pr if f["kind"] == "num"])
    n4 = emit("MachineOptions",    [f for f in pr if f["kind"] == "check"])
    print("ManualMovement    %3d controls" % n1)
    print("MachineStatus     %3d controls" % n2)
    print("MachineParameters %3d controls" % n3)
    print("MachineOptions    %3d controls" % n4)

